/* Standardise one raw feature vector in place. */
static inline void fd_scale(float *features) {
    for (int i = 0; i < FD_NUM_FEATURES; i++) {
        features[i] = (features[i] - FD_SCALER_MEAN[i]) / FD_SCALER_SCALE[i];
    }
}

/*
 * Classify a raw (unscaled) feature vector.
 * Optionally writes the winning decision value to `out_score`.
 */
static inline int fd_predict(const float *raw_features, float *out_score) {
    int best_class = 0;
    float best_score = 0.0f;

    for (int c = 0; c < FD_NUM_CLASSES; c++) {
        float score = FD_INTERCEPT[c];
        for (int i = 0; i < FD_NUM_FEATURES; i++) {
            const float scaled =
                (raw_features[i] - FD_SCALER_MEAN[i]) / FD_SCALER_SCALE[i];
            score += scaled * FD_COEF[c][i];
        }
        if (c == 0 || score > best_score) {
            best_score = score;
            best_class = c;
        }
    }

    if (out_score != 0) {
        *out_score = best_score;
    }
    return best_class;
}

